from uuid import uuid4

import pytest
from pydantic import Field, ValidationError

from cynthus.messaging.common.signal.lifecycle_action import LifecycleAction
from cynthus.messaging.common.signal.message import SignalMessage
from cynthus.messaging.common.signal.message_base import SignalMessageBase
from cynthus.messaging.common.signal.payload import SignalPayload


class Greeting(SignalPayload):
    text: str = Field(...)


def envelope():
    return dict(
        event_type='public.test.greeting.created',
        lifecycle_action=LifecycleAction.CREATED,
        correlation_id=uuid4(),
        organization_id=uuid4(),
        workspace_id=uuid4(),
        actor_id=uuid4(),
    )


def test_extends_the_message_envelope():
    assert issubclass(SignalMessage, SignalMessageBase)


def test_payload_is_required():
    with pytest.raises(ValidationError):
        SignalMessage(**envelope())


def test_unparameterised_message_accepts_any_signal_payload():
    message = SignalMessage(**envelope(), payload=SignalPayload(schema_version=1))

    assert isinstance(message.payload, SignalPayload)


def test_unparameterised_message_rejects_a_non_payload():
    with pytest.raises(ValidationError):
        SignalMessage(**envelope(), payload='text')


def test_parameterised_message_validates_the_payload_type():
    typed = SignalMessage[Greeting]

    assert typed(**envelope(), payload={'schema_version': 1, 'text': 'hi'}).payload.text == 'hi'

    with pytest.raises(ValidationError):
        typed(**envelope(), payload={'schema_version': 1})


def test_parameterised_message_round_trips_through_json():
    typed = SignalMessage[Greeting]
    message = typed(**envelope(), payload=Greeting(schema_version=2, text='hello'))

    assert typed.model_validate_json(message.model_dump_json()) == message


def test_parameterised_messages_are_distinct_types():
    assert SignalMessage[Greeting] is not SignalMessage
    assert issubclass(SignalMessage[Greeting], SignalMessage)
